import React from 'react';

import { getWorkoutTrackMarkup } from '@apps/Workouts/@services/workoutTrackMarkup.service';
import { IWorkoutTrackMarkup } from '@apps/Workouts/@types/workoutTrackMarkup.types';
import WorkoutTrackMarkupItem from '@apps/Workouts/components/WorkoutMarkupEdit/components/WorkoutTrackMarkupItem';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

import HikingTrackListItem from './HikingTrackListItem';
import { getHikingGpx } from '../../../@services/hikingResults.service';
import { IHikingGpx } from '../../../@types/hiking.types';

const SelectHikingTrackModal = ({
  id_hiking,
  withBreak = false,
  onSave,
}: {
  id_hiking: number;
  onSave: (workout: IHikingGpx, workoutMarkup?: IWorkoutTrackMarkup) => void;
  withBreak?: boolean;
}) => {
  const [data, setData] = React.useState<IHikingGpx[]>([]);
  const [breaks, setBreaks] = React.useState<IWorkoutTrackMarkup[]>([]);
  const [selectedHikingTrack, setSelectedHikingTrack] = React.useState<IHikingGpx | null>(null);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const woRes = await getHikingGpx(id_hiking);
        setData(woRes);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_hiking]);

  React.useEffect(() => {
    if (!selectedHikingTrack) return;
    const loadBreaks = async () => {
      try {
        setIsLoading(true);
        const fetchedBreaks = await getWorkoutTrackMarkup(selectedHikingTrack.id_workout_track);
        if (!fetchedBreaks.length) onSave(selectedHikingTrack);
        setBreaks(fetchedBreaks);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };
    loadBreaks();
  }, [selectedHikingTrack]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  return (
    <div style={{ overflowY: 'auto', maxHeight: 400 }}>
      {breaks.length > 0 ? (
        <PohList
          data={breaks.map((d) => ({
            key: d.id,
            action: true,
            onClick: () => selectedHikingTrack && onSave(selectedHikingTrack, d),
            content: <WorkoutTrackMarkupItem markup={d} />,
          }))}
        />
      ) : (
        <PohList
          data={data.map((d) => ({
            key: d.id,
            action: true,
            onClick: () => (withBreak ? setSelectedHikingTrack(d) : onSave(d)),
            content: <HikingTrackListItem hikingGpxTrack={d} />,
          }))}
        />
      )}
    </div>
  );
};

export const selectHikingTrackInModalAsync = (
  id_hiking: number,
  withBreak = false,
): Promise<{ hikingTrack: IHikingGpx; hikingBreak?: IWorkoutTrackMarkup }> =>
  new Promise((resolve) => {
    showModal({
      title: 'Выбор трека похода',
      children: (closeHandler: any) => (
        <SelectHikingTrackModal
          onSave={(hikingTrack, hikingBreak) => {
            resolve({ hikingTrack, hikingBreak });
            closeHandler();
          }}
          withBreak={withBreak}
          id_hiking={id_hiking}
        />
      ),
    });
  });

export default {};
