import React from 'react';

import * as L from 'leaflet';
import { useNavigate } from 'react-router-dom';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { getSQLDate } from '@helpers/dateHelper';
import notificationHelper from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import HikingObstacleListItem from './HikingObstacleListItem';
import { obstacleTypeNameResource } from '../../Obstacles/@resources/obstacles.resource';
import ObstacleListItem from '../../Obstacles/components/ObstaclesByTypePage/ObstacleListItem';
import { searchAndSelectObstacleInModalAsync } from '../../Obstacles/components/ObstacleSelectModal';
import { getRouteObjectsAsync } from '../../Routes/@services/routes.service';
import { IBaseRouteObjectPoint, RouteObjectType } from '../../Routes/@types/routes.types';
import { getHikingDataAsync } from '../@services/hiking.service';
import { addHikingObstacle, getHikingObstaclesList } from '../@services/hikingObstacles.service';
import { getHikingAccessGroupAsync } from '../@services/hikingRules.service';
import { IHikingObstacleCreateDTO } from '../@types/DTO/hikingObstacles.dto.types';
import { HikingAccessGroup } from '../@types/hiking.rules';
import { IHikingData } from '../@types/hiking.types';
import { IHikingObstacleWithObstacleListItem } from '../@types/hikingObstacles.types';
import { selectHikingTrackInModalAsync } from '../tracks/HikingTracks/components/selectHikingTrackHelper';

interface IHikingObstaclesPageProps {
  id_hiking: number;
  search?: string;
}

const HikingObstaclesPage: React.FC<IHikingObstaclesPageProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [hikingObstacles, setHikingObstacles] = React.useState<
    IHikingObstacleWithObstacleListItem[]
  >([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [canEdit, setCanEdit] = React.useState(false);

  const navigate = useNavigate();

  const [routeObjectsWithObstacles, setRouteObjectsWithObstacles] = React.useState<
    IBaseRouteObjectPoint[]
  >([]);

  React.useEffect(() => {
    const start = async () => {
      const hd = await getHikingDataAsync(id_hiking);
      setHikingData(hd);

      const od = await getHikingObstaclesList(id_hiking);
      setHikingObstacles(od);

      if (hd.route.id) {
        const data = await getRouteObjectsAsync(hd.route.id);
        const fd = data.filter(
          (d) => d.type === RouteObjectType.Point && d.obstacle !== null,
        ) as IBaseRouteObjectPoint[];
        setRouteObjectsWithObstacles(fd);
      }

      const accessGroup = await getHikingAccessGroupAsync(id_hiking);
      setCanEdit(
        [
          HikingAccessGroup.Full,
          HikingAccessGroup.All,
          HikingAccessGroup.Boss,
          HikingAccessGroup.Routes,
        ].includes(accessGroup),
      );
    };

    start().finally(() => setIsLoading(false));
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (!hikingData) {
    return null;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          {
            href: `/hiking/${id_hiking}/obstacles`,
            text: 'Локальные препятствия и POI',
            active: true,
          },
        ]}
      />
      <h3 className="mb-3">Локальные препятствия и POI похода «{hikingData.name}»</h3>
      {hikingData.finish > new Date() && (
        <>
          <PohRow>
            <PohCol sm={12}>
              <h4 className="mb-3">Запланированы для прохождения</h4>
              <PohList
                data={routeObjectsWithObstacles.map((o) => {
                  if (!o.obstacle) return { key: o.id };
                  return {
                    key: o.id,
                    children: <ObstacleListItem obstacle={o.obstacle} />,
                    action: true,
                    onClick: () => {
                      navigate(`/hiking/${id_hiking}/obstacles/${o.obstacle?.id}`);
                    },
                  };
                })}
              />
            </PohCol>
          </PohRow>
        </>
      )}

      <section>
        <PageHeader title="Пройдены в походе">
          {canEdit && (
            <PohButton
              variant={ButtonVariant.Success}
              onClick={async () => {
                const { hikingTrack, hikingBreak } = await selectHikingTrackInModalAsync(
                  hikingData.id,
                  true,
                );
                const bb = new L.LatLngBounds(hikingTrack.bounds).pad(1.5);

                const selectedObstacle = await searchAndSelectObstacleInModalAsync({
                  bounds: [
                    bb.getNorthWest().lat,
                    bb.getNorthWest().lng,
                    bb.getSouthEast().lat,
                    bb.getSouthEast().lng,
                  ],
                });

                const data: IHikingObstacleCreateDTO = {
                  id_hiking,
                  id_obstacle: selectedObstacle.id,
                  id_hiking_track: hikingTrack?.id ?? null,
                  id_track_markup: hikingBreak?.id ?? null,
                  description: hikingBreak?.name ?? '',
                  description_in: '',
                  description_out: '',
                  date_in: getSQLDate(hikingBreak?.utcD1 ?? hikingTrack.start, false),
                  date_out: getSQLDate(hikingBreak?.utcD2 ?? hikingTrack.finish, false),
                };

                const createdHikingObstacleId = await addHikingObstacle(data);
                notificationHelper.success(
                  `${obstacleTypeNameResource[selectedObstacle.type]} ${selectedObstacle.name} добавлен(а)`,
                );
                navigate(
                  `/hiking/${id_hiking}/obstacles/${selectedObstacle.id}/${createdHikingObstacleId}/edit`,
                );
              }}
            >
              Добавить
            </PohButton>
          )}
        </PageHeader>
        <h4 className="mb-3"></h4>
        {hikingObstacles.length > 0 ? (
          <PohList
            data={hikingObstacles.map((o) => {
              if (!o.obstacle) return { key: o.id };
              return {
                key: o.id,
                children: <HikingObstacleListItem obstacleItem={o} />,

                action: true,
                onClick: () => {
                  navigate(`/hiking/${id_hiking}/obstacles/${o.obstacle.id}`);
                },
              };
            })}
          />
        ) : (
          <Empty>Для этого похода пусто...</Empty>
        )}
      </section>
    </PohContainer>
  );
};

export default HikingObstaclesPage;
